Bank practice session.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8;

contract Simplebank{

    uint public totalAcounts;
    string public bankname;
    uint public totalBalance;
    string public username;


    constructor(string memory _bankname) { 

        bankname= _bankname;
        totalAcounts=0;
        totalBalance=0;

    }

    function createAccount(string memory _user, uint _deposit) public {
        username= _user;
        totalBalance= _deposit;
        totalAcounts +=1;

    }


    function getbankinfo()public view returns (string memory, uint , uint){
      return (  bankname, totalAcounts,  totalBalance);
    }


}

